-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",     CASE         WHEN TRUNC(SYSDATE) BETWEEN NVL(sd.START_DATE,TRUNC(SYSDATE))              AND NVL(sd.END_DATE, TRUNC(SYSDATE)+999999) THEN 'ACTIVE'         WHEN sd.START_DATE &gt; TRUNC(SYSDATE) THEN 'FUTURE'         ELSE 'EXPIRED'     END                                                   AS \"Substitution Status\",     sd.ITEM                                               AS \"Primary Item ID\",     pim.ITEM_DESC                                         AS \"Primary Item Description\",     pim.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     sd.SUB_ITEM                                           AS \"Substitute Item ID\",     sim.ITEM_DESC                                         AS \"Substitute Item Description\",     sd.LOCATION                                           AS \"Location ID\",     sd.LOC_TYPE                                           AS \"Location Type\",     CASE sd.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END                                                           AS \"Location Name\",     sd.SUBSTITUTE_REASON                                  AS \"Substitution Reason Code\",     CASE sd.SUBSTITUTE_REASON         WHEN 'O' THEN 'Out of Stock' WHEN 'D' THEN 'Discontinued'         WHEN 'S' THEN 'Seasonal'     WHEN 'P' THEN 'Promotional'         ELSE NVL(sd.SUBSTITUTE_REASON,'Not Specified') END AS \"Substitution Reason Description\",     sd.START_DATE                                         AS \"Start Date\",     sd.END_DATE                                           AS \"End Date\",     pils.STOCK_ON_HAND                                    AS \"Primary Item Stock on Hand\",     sils.STOCK_ON_HAND                                    AS \"Substitute Item Stock on Hand\",     CASE WHEN NVL(sils.STOCK_ON_HAND,0) &gt; 0 AND sil.STATUS IN ('A','C')          THEN 'AVAILABLE' ELSE 'OUT OF STOCK' END         AS \"Substitute Availability\",     ril.REPL_METHOD                                       AS \"Replenishment Method\",     sh.CREATE_DATETIME                                    AS \"Record Created Date\"  FROM  MFCS_RDS.RDS_WV_SUB_ITEMS_DETAIL        sd JOIN  MFCS_RDS.RDS_WV_SUB_ITEMS_HEAD          sh  ON sd.ITEM = sh.ITEM AND sd.LOCATION = sh.LOCATION JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             pim ON sd.ITEM     = pim.ITEM JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             sim ON sd.SUB_ITEM = sim.ITEM JOIN  MFCS_RDS.RDS_WV_DEPS                    d   ON pim.DEPT = d.DEPT LEFT JOIN MFCS_RDS.RDS_WV_STORE               st  ON sd.LOCATION = st.STORE AND sd.LOC_TYPE = 'S' LEFT JOIN MFCS_RDS.RDS_WV_WH                  wh  ON sd.LOCATION = wh.WH   AND sd.LOC_TYPE = 'W' LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC            pil ON sd.ITEM     = pil.ITEM AND sd.LOCATION = pil.LOC LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC            sil ON sd.SUB_ITEM = sil.ITEM AND sd.LOCATION = sil.LOC LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH        pils ON sd.ITEM    = pils.ITEM AND sd.LOCATION = pils.LOC LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH        sils ON sd.SUB_ITEM= sils.ITEM AND sd.LOCATION = sils.LOC LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC       ril ON sd.ITEM = ril.ITEM AND sd.LOCATION = ril.LOCATION  WHERE     pim.DEPT = pim.DEPT     AND sd.LOC_TYPE = sd.LOC_TYPE     AND sd.LOCATION = sd.LOCATION</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Substitution Status</ds:name><ds:datatype>varchar(7)</ds:datatype></ds:column><ds:column><ds:name>Primary Item ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Primary Item Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><